 "content": "def transform(grid):
    """Draw a color-3 bent connector from marker 1 toward marker 2.

    Advance diagonally toward the second marker while both coordinates have
    more than one cell remaining, then continue along the longer axis, stopping
    diagonally adjacent to marker 2.
    """
    out = [row[:] for row in grid]
    markers = {}
    for r, row in enumerate(grid):
        for c, value in enumerate(row):
            if value in (1, 2):
                markers[value] = (r, c)
    if 1 not in markers or 2 not in markers:
        return out
    r, c = markers[1]
    tr, tc = markers[2]
    sr = 1 if tr > r else -1 if tr < r else 0
    sc = 1 if tc > c else -1 if tc < c else 0

    # The diagonal segment runs until the shorter coordinate is one cell
    # away from the target; the remaining segment is axis-aligned.
    diagonal_steps = max(0, min(abs(tr - r), abs(tc - c)) - 1)
    for _ in range(diagonal_steps):
        r += sr
        c += sc
        out[r][c] = 3

    while (r, c) != (tr - sr, tc - sc):
        if abs(tr - r) >= abs(tc - c):
            r += sr
        else:
            c += sc
        out[r][c] = 3
    return out
